import json, subprocess, sys, os
BASE=dict(early=False,overlap="reject",buffer_packets=2,idle_ms=0,
 max_streams_bidi=4,max_streams_uni=4,max_stream_data=32,max_data=64,crypto_limit=32,
 sent={"I":[],"H":[],"A":[]})
def run(events, **cfg):
    c=dict(BASE); c.update(cfg)
    req={"version":1,"traces":[{"id":"t","config":c,"events":events}]}
    p=subprocess.run([sys.executable,"-I","/app/submission/entry.py"],input=json.dumps(req).encode(),capture_output=True)
    if p.returncode!=0:
        print("CRASH",p.returncode,p.stderr.decode()); return None
    try: return json.loads(p.stdout)
    except Exception:
        print("BADOUT",p.stdout[:500]); return None
def ev(t, packets, size=1200): return {"t":t,"op":"datagram","bytes":size,"packets":packets}
def pkt(level,pn,frames,auth=True): return {"level":level,"pn":pn,"auth":auth,"frames":frames}
def st(id,off,hx,fin=False): return {"type":"STREAM","id":id,"offset":off,"data_hex":hx,"fin":fin}
def cr(off,hx): return {"type":"CRYPTO","offset":off,"data_hex":hx}
def key(t,l,a): return {"t":t,"op":"key","level":l,"action":a}
def tick(t): return {"t":t,"op":"tick"}
if __name__=="__main__":
    pass
PY
